create or replace function public.svc_layer1_run_progress(p_run_id uuid,p_status text,p_stage text,p_processed bigint default null,p_created bigint default null,p_updated bigint default null,p_unchanged bigint default null,p_rejected bigint default null,p_conflicted bigint default null,p_failed bigint default null,p_actual_job_id uuid default null,p_result jsonb default null,p_error text default null,p_source_hash text default null,p_resume_cursor bigint default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,pipeline as $$ declare v_source uuid; v_mode text; v_expected bigint; begin if p_status not in ('queued','running','completed','failed','cancelled','blocked','no_change') then raise exception 'invalid status'; end if; update pipeline.layer1_run_queue set status=p_status,current_stage=coalesce(nullif(p_stage,''),current_stage),heartbeat_at=now(),started_at=case when p_status='running' then coalesce(started_at,now()) else started_at end,completed_at=case when p_status in ('completed','failed','cancelled','blocked','no_change') then coalesce(completed_at,now()) else completed_at end,processed_count=coalesce(p_processed,processed_count),created_count=case when p_created is null then created_count else created_count+p_created end,updated_count=case when p_updated is null then updated_count else updated_count+p_updated end,unchanged_count=case when p_unchanged is null then unchanged_count else unchanged_count+p_unchanged end,rejected_count=case when p_rejected is null then rejected_count else rejected_count+p_rejected end,conflicted_count=case when p_conflicted is null then conflicted_count else conflicted_count+p_conflicted end,failed_count=case when p_failed is null then failed_count else failed_count+p_failed end,actual_job_id=coalesce(p_actual_job_id,actual_job_id),result=case when p_result is null then result else result||p_result end,error_text=case when p_error is null then error_text else left(p_error,1800) end,source_hash=coalesce(p_source_hash,source_hash),resume_cursor=coalesce(p_resume_cursor,resume_cursor),updated_at=now() where id=p_run_id returning source_id,mode,expected_count into v_source,v_mode,v_expected; if not found then raise exception 'run not found'; end if; if p_status in ('completed','no_change') and v_mode='apply' then update pipeline.layer1_source_operations set previous_accepted_count=coalesce(v_expected,previous_accepted_count),previous_accepted_hash=coalesce(p_source_hash,previous_accepted_hash),last_source_hash=coalesce(p_source_hash,last_source_hash),next_ingestion_at=case when ingestion_cadence_days is null then null else now()+make_interval(days=>ingestion_cadence_days) end,last_schedule_status=p_status,last_schedule_error=null,updated_at=now() where source_id=v_source; elsif p_status in ('failed','blocked') then update pipeline.layer1_source_operations set last_schedule_status=p_status,last_schedule_error=left(coalesce(p_error,p_status),1000),consecutive_failures=consecutive_failures+1,updated_at=now() where source_id=v_source; end if; return jsonb_build_object('run_id',p_run_id,'status',p_status,'stage',p_stage); end $$; revoke all on function public.svc_layer1_run_progress(uuid,text,text,bigint,bigint,bigint,bigint,bigint,bigint,bigint,uuid,jsonb,text,text,bigint) from public,anon,authenticated; grant execute on function public.svc_layer1_run_progress(uuid,text,text,bigint,bigint,bigint,bigint,bigint,bigint,bigint,uuid,jsonb,text,text,bigint) to service_role;

create or replace function security.admin_layer1_command(p_operation text,p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog,security,pipeline,ref,auth as $$
declare v_rank integer; v_source uuid; v_reason text; v_id uuid; v_country text; v_mode text; v_version integer; v_warning boolean; v_url text; v_profile jsonb; v_domains text[];
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if; select security.current_role_rank() into v_rank; if coalesce(v_rank,0)<6 then raise exception 'platform_admin role required' using errcode='42501'; end if; v_source:=nullif(p_args->>'source_id','')::uuid; if v_source is null then raise exception 'source_id required' using errcode='22023'; end if; v_reason:=trim(coalesce(p_args->>'reason','')); if length(v_reason)<5 then raise exception 'governance reason required' using errcode='22023'; end if;
 if p_operation='save_source' then
  select url into v_url from pipeline.sources where id=v_source; if not found then raise exception 'source not found' using errcode='22023'; end if; v_url:=coalesce(nullif(trim(p_args->>'source_url',''),''),v_url); if v_url !~* '^https://[^[:space:]]+$' then raise exception 'https source_url required' using errcode='22023'; end if; select array_agg(lower(trim(x))) into v_domains from jsonb_array_elements_text(coalesce(p_args->'authority_domains','[]'::jsonb)) x where trim(x)<>''; if coalesce(cardinality(v_domains),0)=0 then raise exception 'at least one authority domain required' using errcode='22023'; end if; if length(trim(coalesce(p_args->>'authority_name','')))<3 then raise exception 'authority_name required' using errcode='22023'; end if; if length(trim(coalesce(p_args->>'expected_format','')))<2 then raise exception 'expected_format required' using errcode='22023'; end if;
  update pipeline.sources set url=v_url,updated_at=now() where id=v_source;
  insert into pipeline.layer1_source_operations(source_id,authority_name,authority_domains,expected_format,expected_count_kind,active,paused,verification_cadence_days,ingestion_cadence_days,variance_warn_percent,variance_block_percent,min_expected_records,max_expected_records,verification_status,variance_decision,last_verified_at,verification_message,next_verification_at,change_reason,updated_by,updated_at)
  values(v_source,trim(p_args->>'authority_name'),v_domains,trim(p_args->>'expected_format'),coalesce(nullif(trim(p_args->>'expected_count_kind'),''),'records'),coalesce((p_args->>'active')::boolean,true),coalesce((p_args->>'paused')::boolean,false),coalesce(nullif(p_args->>'verification_cadence_days','')::integer,1),nullif(p_args->>'ingestion_cadence_days','')::integer,coalesce(nullif(p_args->>'variance_warn_percent','')::numeric,5),coalesce(nullif(p_args->>'variance_block_percent','')::numeric,20),nullif(p_args->>'min_expected_records','')::bigint,nullif(p_args->>'max_expected_records','')::bigint,'unverified','unknown',null,'Source configuration changed; source must be revalidated before execution.',now(),v_reason,auth.uid(),now())
  on conflict(source_id) do update set authority_name=excluded.authority_name,authority_domains=excluded.authority_domains,expected_format=excluded.expected_format,expected_count_kind=excluded.expected_count_kind,active=excluded.active,paused=excluded.paused,verification_cadence_days=excluded.verification_cadence_days,ingestion_cadence_days=excluded.ingestion_cadence_days,variance_warn_percent=excluded.variance_warn_percent,variance_block_percent=excluded.variance_block_percent,min_expected_records=excluded.min_expected_records,max_expected_records=excluded.max_expected_records,verification_status='unverified',variance_decision='unknown',last_verified_at=null,verification_message='Source configuration changed; source must be revalidated before execution.',next_verification_at=now(),change_reason=excluded.change_reason,updated_by=auth.uid(),updated_at=now();
  select coalesce(max(version_no),0)+1 into v_version from pipeline.layer1_source_operation_versions where source_id=v_source; select to_jsonb(o)-'updated_by' into v_profile from pipeline.layer1_source_operations o where o.source_id=v_source; insert into pipeline.layer1_source_operation_versions(source_id,version_no,snapshot,changed_by,change_reason) values(v_source,v_version,v_profile,auth.uid(),v_reason); return jsonb_build_object('source_id',v_source,'version_no',v_version,'status','saved_revalidation_required');
 elsif p_operation='set_pause' then update pipeline.layer1_source_operations set paused=coalesce((p_args->>'paused')::boolean,true),change_reason=v_reason,updated_by=auth.uid(),updated_at=now() where source_id=v_source returning to_jsonb(layer1_source_operations)-'updated_by' into v_profile; if not found then raise exception 'source operations profile missing' using errcode='22023'; end if; select coalesce(max(version_no),0)+1 into v_version from pipeline.layer1_source_operation_versions where source_id=v_source; insert into pipeline.layer1_source_operation_versions(source_id,version_no,snapshot,changed_by,change_reason) values(v_source,v_version,v_profile,auth.uid(),v_reason); update pipeline.refresh_policies set enabled=not coalesce((p_args->>'paused')::boolean,true),updated_at=now(),change_control_ref='CF-CHG-20260826-043' where layer=1 and source_id=v_source; return jsonb_build_object('source_id',v_source,'paused',v_profile->'paused','version_no',v_version);
 elsif p_operation='queue_run' then select to_jsonb(o) into v_profile from pipeline.layer1_source_operations o where o.source_id=v_source; if not found then raise exception 'source operations profile missing' using errcode='22023'; end if; select co.iso_alpha2::text into v_country from pipeline.sources s join ref.countries co on co.id=s.country_id where s.id=v_source; v_mode:=lower(coalesce(nullif(p_args->>'mode',''),'dry_run')); if v_mode not in ('validate','dry_run','apply','recheck') then raise exception 'invalid mode' using errcode='22023'; end if; if not coalesce((v_profile->>'active')::boolean,false) or coalesce((v_profile->>'paused')::boolean,false) then raise exception 'source is inactive or paused' using errcode='55000'; end if; if v_mode in ('dry_run','apply','recheck') then if coalesce(v_profile->>'verification_status','') not in ('passed','warning') then raise exception 'source verification must pass before run' using errcode='55000'; end if; if nullif(v_profile->>'next_verification_at','')::timestamptz is not null and (v_profile->>'next_verification_at')::timestamptz<now() then raise exception 'source verification is stale' using errcode='55000'; end if; if v_profile->>'variance_decision'='block' then raise exception 'record-count variance is blocked' using errcode='55000'; end if; v_warning:=v_profile->>'variance_decision'='warn'; if v_mode='apply' and v_warning and not coalesce((p_args->>'acknowledge_warning')::boolean,false) then raise exception 'variance warning acknowledgement required for APPLY' using errcode='55000'; end if; end if; insert into pipeline.layer1_run_queue(source_id,country_code,mode,status,idempotency_key,requested_by,expected_count,resume_cursor,source_hash,warning_acknowledged,current_stage,heartbeat_at,retry_of_run_id) values(v_source,v_country,v_mode,'queued',coalesce(nullif(p_args->>'idempotency_key',''),md5(v_source::text||':'||v_mode||':'||coalesce(v_profile->>'last_source_hash','nohash')||':'||coalesce(p_args->>'resume_cursor','0')||':'||current_date::text)),auth.uid(),nullif(v_profile->>'last_expected_count','')::bigint,coalesce(nullif(p_args->>'resume_cursor','')::bigint,0),v_profile->>'last_source_hash',coalesce((p_args->>'acknowledge_warning')::boolean,false),'queued',now(),nullif(p_args->>'retry_of_run_id','')::uuid) returning id into v_id; return jsonb_build_object('run_id',v_id,'status','queued','country_code',v_country,'mode',v_mode);
 elsif p_operation='cancel_queued' then v_id:=nullif(p_args->>'run_id','')::uuid; update pipeline.layer1_run_queue set status='cancelled',current_stage='cancelled_before_start',completed_at=now(),updated_at=now(),error_text='Cancelled by Platform Admin: '||v_reason where id=v_id and source_id=v_source and status='queued'; if not found then raise exception 'only queued run may be cancelled' using errcode='55000'; end if; return jsonb_build_object('run_id',v_id,'status','cancelled'); else raise exception 'unsupported Layer 1 command: %',p_operation using errcode='22023'; end if;
end $$;
revoke all on function security.admin_layer1_command(text,jsonb) from public,anon; grant execute on function security.admin_layer1_command(text,jsonb) to authenticated,service_role;